update public.learning_paths
set
  title = 'Asian Religions',
  goal = 'Asian Religions',
  summary = 'Students begin by learning how scholars define religion, Asia, tradition, scripture, ritual, philosophy, and lived practice without flattening diverse communities into a single essence. The course studies Vedic sacrifice and social order, the philosophical and soteriological vocabulary of Upanishadic and classical thought, plural Hindu practice, early Buddhism and later Mahayana and Vajrayana traditions, Jain and Sikh ethics, Chinese religious worlds, Daoism, Confucianism, East Asian Buddhism, Japanese traditions, Southeast Asian landscapes, and modern diaspora, reform, and comparative interpretation.',
  data = $asrejson${"slug": "asian-religions", "title": "Asian Religions", "description": "Students begin by learning how scholars define religion, Asia, tradition, scripture, ritual, philosophy, and lived practice without flattening diverse communities into a single essence. The course studies Vedic sacrifice and social order, the philosophical and soteriological vocabulary of Upanishadic and classical thought, plural Hindu practice, early Buddhism and later Mahayana and Vajrayana traditions, Jain and Sikh ethics, Chinese religious worlds, Daoism, Confucianism, East Asian Buddhism, Japanese traditions, Southeast Asian landscapes, and modern diaspora, reform, and comparative interpretation.", "topics": [{"id": "5cbffde7-dca3-497c-aaf4-b8b93b2a5a97", "type": "topic", "title": "Studying Asian Religions: Method, Category, Region, Text, Ritual, and Lived Practice", "description": "Students begin by learning how scholars define religion, Asia, tradition, scripture, ritual, philosophy, and lived practice without flattening diverse communities into a single essence.", "children": [{"id": "9cee162f-ee5a-4c38-b257-dac15da82392", "type": "subtopic", "title": "Method and vocabulary", "children": [{"id": "494a658f-1060-4595-b673-36ff2a5f53a7", "type": "concept", "title": "Religion, philosophy, ritual, scripture, myth, doctrine, practice, lineage, community, and tradition"}, {"id": "b6b8e835-44c1-4a17-8867-07196bea1a3f", "type": "concept", "title": "Insider/outsider perspectives and scholarly description"}, {"id": "98d24aaa-0b5f-4813-921b-a0605f3d1f31", "type": "concept", "title": "Avoiding essentialism and romanticism"}], "description": "Students learn how to study traditions comparatively without reducing them to stereotypes."}, {"id": "48caa754-f762-408e-81ae-8cd9e6cbfb64", "type": "subtopic", "title": "Asia as a category", "children": [{"id": "528ff4e5-6964-47de-9a05-6885c8002921", "type": "concept", "title": "South Asia, East Asia, Southeast Asia, Central Asia, diaspora, and transnational networks"}, {"id": "ea750dd3-0bf2-471b-acff-e868ad27c360", "type": "concept", "title": "Trade, migration, empire, translation, pilgrimage, and colonial borders"}, {"id": "1d090196-fbcf-4d53-989b-44381383d685", "type": "concept", "title": "Regional comparison and local specificity"}], "description": "The point is to treat Asia as historical and geographic complexity, not a single religious civilization."}, {"id": "9e7beecd-b178-4fe4-b0e4-10d2695b5d16", "type": "subtopic", "title": "Sources and evidence", "children": [{"id": "a366ba5a-15f5-4b98-ab0d-27464f3d2ae7", "type": "concept", "title": "Texts, inscriptions, art, architecture, ritual manuals, oral tradition, ethnography, film, digital media, and community practice"}, {"id": "0791b7e8-c97c-48bf-8502-8678733365cb", "type": "concept", "title": "Primary versus secondary sources"}, {"id": "9fafbec1-ccc7-467e-b306-482964b08600", "type": "concept", "title": "Translation, context, and power"}], "description": "Students learn to interpret multiple kinds of religious evidence."}]}, {"id": "7ba2d970-8246-4edc-bb1a-bdf559403e30", "type": "topic", "title": "Vedic Religion, Sacrifice, Caste, Cosmology, and Early South Asian Ritual Worlds", "description": "This module introduces the Vedic foundations of South Asian religious history, including sacrifice, gods, social order, oral transmission, and ritual authority.", "children": [{"id": "da84e1ba-cc2d-434e-8b8f-83e0bb2f3158", "type": "subtopic", "title": "Vedic texts and ritual", "children": [{"id": "f3a3a8fe-b1ae-4cbe-8220-ca1299fe9d7c", "type": "concept", "title": "Rig Veda, Sama Veda, Yajur Veda, Atharva Veda, Brahmanas, Aranyakas, and oral transmission"}, {"id": "51eb2666-e2a7-48c2-8983-d8e528f25ed0", "type": "concept", "title": "Sacrifice, mantra, priesthood, fire ritual, soma, and cosmic order"}, {"id": "b409eb4b-4e19-453c-b3c0-a7130d64427e", "type": "concept", "title": "Authority and memory in oral tradition"}], "description": "Students learn the ritual and textual foundations of early South Asian religion."}, {"id": "9054d80d-a2d5-4d7c-a6ba-708257c25bf2", "type": "subtopic", "title": "Gods and cosmology", "children": [{"id": "4deee3f3-94b6-455d-a8e7-69111c83ae25", "type": "concept", "title": "Indra, Agni, Varuna, Soma, Ushas, Prajapati, and cosmic creation hymns"}, {"id": "97dca27f-2748-44c8-948a-6acb2ea163ac", "type": "concept", "title": "Rta, sacrifice, reciprocity, and world maintenance"}, {"id": "63f6ab90-b69f-4e98-9ed9-d79fdb42f878", "type": "concept", "title": "Myth, ritual, and social order"}], "description": "The gist is to understand early divine worlds before later Hindu devotional forms."}, {"id": "2073182f-f740-4d3a-801e-de49c2000dd0", "type": "subtopic", "title": "Social formation", "children": [{"id": "2e49ec49-be85-488e-84a4-e8274942afdb", "type": "concept", "title": "Varna, jati, purity, gender, household ritual, and kinship"}, {"id": "bc4d434a-86fb-4c95-86fc-7acf98d2c5c4", "type": "concept", "title": "Dharma and social duty"}, {"id": "a9a0a53f-a5ce-4a12-83ff-20682da74f5e", "type": "concept", "title": "Scholarly debates about caste, ritual authority, and historical change"}], "description": "Students study the emergence and contestation of hierarchy."}]}, {"id": "e11e5cc4-cf5c-430a-8e89-f9ab7a9018f7", "type": "topic", "title": "Upanishads, Yoga, Samkhya, Vedanta, Dharma, Karma, and Moksha", "description": "Students study the philosophical and soteriological vocabulary that shapes many Hindu, Buddhist, Jain, and later South Asian traditions.", "children": [{"id": "2251fe5e-9dc3-418a-bfc9-ab8b18cbdf88", "type": "subtopic", "title": "Upanishadic thought", "children": [{"id": "0cf4608d-bbb5-4161-b4bb-18c129a6f7ba", "type": "concept", "title": "Atman, Brahman, samsara, karma, moksha, knowledge, meditation, and renunciation"}, {"id": "52bf59f6-dca7-481a-9ca6-3c58172e17ea", "type": "concept", "title": "Dialogues, paradox, and philosophical inquiry"}, {"id": "fd71fd3b-66c1-483e-8f02-d39fe9c3114b", "type": "concept", "title": "Continuity and critique of Vedic ritualism"}], "description": "Students learn key concepts of self, reality, and liberation."}, {"id": "2502078b-cac8-4968-a362-18399cc99be1", "type": "subtopic", "title": "Classical philosophies", "children": [{"id": "93188069-9162-4d61-b3b9-91b1878ae259", "type": "concept", "title": "Yoga, Samkhya, Vedanta, Nyaya, Mimamsa, Vaisheshika, and Buddhist/Jain critiques"}, {"id": "ab20ae1d-b7b9-4f1a-bf44-8b340a795f85", "type": "concept", "title": "Liberation, epistemology, cosmology, and discipline"}, {"id": "cbce257a-e873-4b0b-92a0-da16bf03fb5c", "type": "concept", "title": "Commentarial traditions and debate"}], "description": "The point is to connect religious practice with systematic thought."}, {"id": "2e6898de-ba73-4933-975d-34c3fcacd9ba", "type": "subtopic", "title": "Dharma and ethics", "children": [{"id": "7c426e78-6325-4a7b-93ac-d2ad680c5dd5", "type": "concept", "title": "Dharma, ashrama, purushartha, family, renunciation, kingship, and social duty"}, {"id": "ec4beeb3-1d38-4b1f-b111-8880f8715b9f", "type": "concept", "title": "Karma and moral causality"}, {"id": "ec304667-5f45-4435-aae5-8e3af59675fa", "type": "concept", "title": "Tensions between liberation and worldly obligation"}], "description": "Students see how religious ideas structure life stages and obligations."}]}, {"id": "19fe4352-24f1-40af-8ab8-02abf6a21f96", "type": "topic", "title": "Hindu Traditions: Deities, Temples, Epics, Bhakti, Tantra, Pilgrimage, and Domestic Practice", "description": "This topic treats Hindu traditions as plural and lived: textual, ritual, devotional, philosophical, regional, household, and transnational.", "children": [{"id": "c68dec2e-2008-4cd9-92f9-84c81c5ce5f7", "type": "subtopic", "title": "Deities and narratives", "children": [{"id": "9e5c8d5a-d833-40eb-a6be-cd59bc40a070", "type": "concept", "title": "Vishnu, Shiva, Devi, Krishna, Rama, Ganesha, local deities, and village goddesses"}, {"id": "7f9eb258-6c82-441d-9eaf-5c55704fc245", "type": "concept", "title": "Ramayana, Mahabharata, Bhagavad Gita, Puranas, and regional retellings"}, {"id": "b6013ece-fbe8-40b0-bb04-1c15b51eade4", "type": "concept", "title": "Myth, theology, performance, and memory"}], "description": "Students learn plural devotional worlds within Hindu traditions."}, {"id": "c301cc1b-c6e8-43cb-934d-6949aec91cb5", "type": "subtopic", "title": "Ritual and place", "children": [{"id": "9dfb1899-054f-4acb-84b8-f6a1d8369bc9", "type": "concept", "title": "Puja, darshan, prasad, pilgrimage, vows, life-cycle rituals, temple economies, and domestic shrines"}, {"id": "bbbd79d8-4cb9-4c0f-9df6-80519d402573", "type": "concept", "title": "Priests, devotees, gurus, ascetics, and householders"}, {"id": "56fa2a6b-eb97-4adc-9ad9-aeee6b8b1c95", "type": "concept", "title": "Ritual time, sacred geography, and embodiment"}], "description": "The gist is to study Hinduism as practiced in homes, temples, festivals, and sacred landscapes."}, {"id": "71c505a9-6214-4b28-ba69-46d3a514df91", "type": "subtopic", "title": "Bhakti, Tantra, and modernity", "children": [{"id": "9f069e5a-fe88-4f50-9494-9426283d95fe", "type": "concept", "title": "Alvars, Nayanmars, saints, poetry, music, and vernacular devotion"}, {"id": "cf9c098c-cf9b-45f9-880f-e325c9a51c01", "type": "concept", "title": "Tantric ritual, mantra, deity embodiment, and esoteric practice"}, {"id": "15508843-f655-4bb6-9c03-05d6f0e3edeb", "type": "concept", "title": "Reform, nationalism, caste critique, gender, and diaspora"}], "description": "Students examine movements of devotion, power, reform, and identity."}]}, {"id": "0c77f983-c52e-4577-a9f0-02c0a211a590", "type": "topic", "title": "Buddha, Early Buddhism, Four Noble Truths, Monasticism, and Theravada Traditions", "description": "Students learn the origin narratives, core teachings, monastic institutions, and early textual traditions of Buddhism.", "children": [{"id": "d37681e0-ba24-409a-a93f-170f344e3953", "type": "subtopic", "title": "Life of the Buddha", "children": [{"id": "ce46127b-c025-4696-98e4-4d58e7313203", "type": "concept", "title": "Birth, renunciation, awakening, teaching, community, and parinirvana"}, {"id": "c8f4bb1e-52c9-487f-b03e-ff0f8149c672", "type": "concept", "title": "Historical Buddha and literary Buddha"}, {"id": "46a6d3da-aafa-45f3-a6e1-f877c17aa484", "type": "concept", "title": "Narrative as doctrine and model"}], "description": "Students learn the foundational narratives and their interpretive roles."}, {"id": "c24db3bc-98ce-4561-9d19-95be85ba9e49", "type": "subtopic", "title": "Core teachings", "children": [{"id": "bba2fafe-9461-4e8d-b28c-b06a2ba80671", "type": "concept", "title": "Four Noble Truths, Eightfold Path, dependent origination, impermanence, non-self, karma, rebirth, nirvana, and meditation"}, {"id": "a81666b0-2e2b-45c8-a483-d2c07e8b0aea", "type": "concept", "title": "Ethics, concentration, and wisdom"}, {"id": "873c338e-7908-4d98-93fc-0bb5be4287ca", "type": "concept", "title": "Middle way and monastic discipline"}], "description": "The point is to understand the Buddhist diagnosis of suffering and liberation."}, {"id": "c54f7f9b-3099-454d-8797-854c3b9919be", "type": "subtopic", "title": "Theravada worlds", "children": [{"id": "09681210-d106-4355-a02b-17d14ca53e19", "type": "concept", "title": "Pali Canon, sangha, merit, dana, monasticism, lay practice, kingship, and reform"}, {"id": "0494e656-a005-44e6-bf4b-86787eb54dcf", "type": "concept", "title": "Sri Lanka, Myanmar, Thailand, Cambodia, and Laos"}, {"id": "7cbfee33-0b9c-4f4d-ab91-da02cf1b694a", "type": "concept", "title": "Modern meditation movements and global Theravada"}], "description": "Students study Buddhist institutions and practice in South and Southeast Asia."}]}, {"id": "f1e8763d-54b9-4c85-ace0-4905ed458a55", "type": "topic", "title": "Mahayana and Vajrayana Buddhism: Bodhisattvas, Emptiness, Pure Lands, Tantra, and Ritual", "description": "This module expands Buddhist study into major later traditions, devotional worlds, philosophical schools, and ritual technologies.", "children": [{"id": "c0101c44-fdc9-4fdc-9e56-681fdb3fccfa", "type": "subtopic", "title": "Mahayana ideals", "children": [{"id": "93c136ea-9e31-40d4-8327-0387ed3a8be2", "type": "concept", "title": "Bodhisattva path, compassion, wisdom, skillful means, Buddha-nature, and multiple buddhas"}, {"id": "afd6ac0b-7777-4897-8c6f-b0e9255399a4", "type": "concept", "title": "Prajnaparamita, Lotus Sutra, Pure Land sutras, and Avatamsaka"}, {"id": "5d183130-cb58-4807-8bd9-7f1807c1d9c0", "type": "concept", "title": "Lay devotion and universal liberation"}], "description": "Students learn expanded Buddhist visions of liberation."}, {"id": "6c76376a-ae21-4da4-977e-ae996c398aba", "type": "subtopic", "title": "Philosophy and practice", "children": [{"id": "cd9be9ae-c701-4331-926d-62f6d293d914", "type": "concept", "title": "Madhyamaka, Yogacara, emptiness, two truths, consciousness, and debate"}, {"id": "312f11b6-ca51-49d6-bf20-357657f365a8", "type": "concept", "title": "Pure Land, chanting, visualization, repentance, and ritual"}, {"id": "171e8db8-cae2-494c-895a-185264a01c92", "type": "concept", "title": "Monastic and lay practice"}], "description": "The gist is to understand major schools and practices."}, {"id": "dc9f0774-5e34-4262-9df9-200dd68e0149", "type": "subtopic", "title": "Vajrayana and tantra", "children": [{"id": "6007aed8-0e44-4dc8-8a60-2d3010daffcb", "type": "concept", "title": "Mantra, mandala, deity yoga, guru, initiation, subtle body, and ritual protection"}, {"id": "3fec4707-56ff-48f3-ad0d-8e291841a0b3", "type": "concept", "title": "Tibetan, Himalayan, Mongolian, and Japanese esoteric traditions"}, {"id": "97c3f654-4b38-4988-8f1e-f4b6f737e7b4", "type": "concept", "title": "Ethics, power, secrecy, and modern reception"}], "description": "Students examine esoteric Buddhist forms responsibly."}]}, {"id": "d771e769-2aca-48f7-9abb-7c5039a95b00", "type": "topic", "title": "Jainism and Sikhism: Nonviolence, Liberation, Guru Traditions, Community, and Ethics", "description": "Students study Jain and Sikh traditions as distinct South Asian religious worlds with their own histories, practices, ethics, and communities.", "children": [{"id": "587709d7-50ea-4e8c-98b1-f61ad95101c1", "type": "subtopic", "title": "Jain traditions", "children": [{"id": "b68d0dbd-7c7c-46ac-b1b8-f84897fcfca6", "type": "concept", "title": "Tirthankaras, Mahavira, jiva, ajiva, karma as substance, asceticism, ahimsa, and liberation"}, {"id": "8e2e1f98-78ae-4d94-ba6b-87db4bdc0524", "type": "concept", "title": "Digambara and Shvetambara traditions"}, {"id": "ff53b1a8-f348-4452-8328-5bd7c250510c", "type": "concept", "title": "Lay vows, monastic ideals, fasting, and pilgrimage"}], "description": "Students learn a major South Asian path centered on nonviolence and liberation."}, {"id": "89258a7a-1c85-48e7-a710-19e9b2e639fd", "type": "subtopic", "title": "Sikh traditions", "children": [{"id": "acbea161-8852-4992-b179-82f651a26248", "type": "concept", "title": "Guru Nanak, ten Gurus, Guru Granth Sahib, sangat, langar, kirtan, seva, and the Khalsa"}, {"id": "785d2f47-9c9d-42e7-8375-3413e20d4d4f", "type": "concept", "title": "Naam, hukam, equality, justice, and devotion"}, {"id": "5205c562-9ed4-4028-8cdb-d3e9968d8f1e", "type": "concept", "title": "Punjab, diaspora, identity, and modern history"}], "description": "The point is to study Sikhism as a distinct religious community and path."}, {"id": "686c4ff0-24e9-49c7-8cf8-bf96821287fa", "type": "subtopic", "title": "Comparative ethics", "children": [{"id": "761ac63b-3ea3-4011-9519-9d78740f733d", "type": "concept", "title": "Ahimsa, service, community, discipline, liberation, social justice, and household life"}, {"id": "f9614f4d-e7fd-4222-8a1a-311291da05da", "type": "concept", "title": "Food, dress, ritual, gender, caste, and authority"}, {"id": "3cfcd96d-a5c4-4351-86fb-4ed33fe5cba3", "type": "concept", "title": "Minority traditions and public representation"}], "description": "Students compare moral worlds without merging them."}]}, {"id": "1b4a1dd8-4b20-4326-8d63-5fdecee56b23", "type": "topic", "title": "Chinese Religious Worlds: Ancestors, Cosmology, Popular Religion, State Ritual, and Syncretism", "description": "This topic introduces Chinese religion as a layered field of ancestral, local, imperial, Buddhist, Daoist, Confucian, and popular practices.", "children": [{"id": "b7f01453-738d-4471-bbe2-821e8d44bb08", "type": "subtopic", "title": "Religious ecology", "children": [{"id": "bee96968-febe-4a32-b386-1d91807fbef1", "type": "concept", "title": "Ancestors, local gods, ghosts, immortals, temples, festivals, divination, feng shui, and spirit mediums"}, {"id": "0e10cd9e-a985-4a40-bbf8-77c84382ac62", "type": "concept", "title": "Family, village, city, state, and market"}, {"id": "3ac56076-6ace-41f5-a25e-25277536d5aa", "type": "concept", "title": "Syncretism, complementarity, and practice-centered religion"}], "description": "Students learn why Chinese religion often resists single-tradition labels."}, {"id": "75ff376a-937b-4c65-863d-c5445b44a11c", "type": "subtopic", "title": "Cosmology and ritual", "children": [{"id": "06ee6059-3d69-4128-953c-f03f186cc640", "type": "concept", "title": "Qi, yin-yang, five phases, Heaven, mandate, ritual propriety, and cosmic resonance"}, {"id": "a38bfc9e-564c-48b9-8c23-d9639de3be19", "type": "concept", "title": "Offerings, calendars, funerals, exorcism, and protection"}, {"id": "48a65981-6de9-4c8c-a81d-91555da66cd3", "type": "concept", "title": "Body, landscape, and bureaucracy"}], "description": "The gist is to understand shared frameworks across traditions."}, {"id": "c9f659dc-5280-498a-91b7-699fa21e200c", "type": "subtopic", "title": "State and society", "children": [{"id": "f10e1dc2-e24f-4e20-9f2e-020e7af5d908", "type": "concept", "title": "Imperial cult, local temples, Confucian state ritual, Buddhist and Daoist institutions, and popular movements"}, {"id": "d7063b8d-a655-402b-a593-e7212eb90614", "type": "concept", "title": "Regulation, suppression, revival, and heritage"}, {"id": "4e01db87-88be-41d6-b86e-d99ae505fb1d", "type": "concept", "title": "Modern China, Taiwan, Hong Kong, and diaspora"}], "description": "Students connect religion to governance and social order."}]}, {"id": "6167a7c4-5cb6-4e3f-8259-0cec1cd2dff7", "type": "topic", "title": "Daoism: Dao, De, Wu Wei, Zhuangzi, Ritual Lineages, Alchemy, and Sacred Ecology", "description": "Students explore Daoism as philosophy, religion, ritual system, textual tradition, self-cultivation path, and ecological/cosmological imagination.", "children": [{"id": "9422d5bb-c696-4292-8d75-1eb4331325ee", "type": "subtopic", "title": "Classical Daoist texts", "children": [{"id": "45662189-4101-463f-bebb-5303ad5a2531", "type": "concept", "title": "Dao De Jing, Zhuangzi, Dao, de, wu wei, spontaneity, naturalness, simplicity, and transformation"}, {"id": "3dea4e36-f266-4f54-82c4-36845367cabf", "type": "concept", "title": "Language, paradox, freedom, and critique of social convention"}, {"id": "a9d7985e-271d-4b6e-b4e6-9feec39abb5e", "type": "concept", "title": "Philosophy and religion as overlapping categories"}], "description": "Students learn central philosophical themes."}, {"id": "9caa4412-6b56-467a-bcc6-609e6e23c0d1", "type": "subtopic", "title": "Religious Daoism", "children": [{"id": "780595ce-b319-4b2e-90af-2077554e0368", "type": "concept", "title": "Celestial Masters, Shangqing, Lingbao, Quanzhen, priests, registers, talismans, liturgy, and sacred mountains"}, {"id": "1699a14f-fae2-495f-bdf6-1516644d29a0", "type": "concept", "title": "Healing, protection, exorcism, funerals, and communal renewal"}, {"id": "beafb5ae-8d12-4080-939a-5070cda6d70a", "type": "concept", "title": "Canon, lineage, ordination, and local practice"}], "description": "The point is to see Daoism as ritual, communal, and institutional."}, {"id": "a4fe27dd-7455-45f1-a383-2f7bdd9f7431", "type": "subtopic", "title": "Self-cultivation and ecology", "children": [{"id": "41c24ae4-a5c3-4366-8be8-eed333566413", "type": "concept", "title": "Meditation, breath, internal alchemy, qigong, dietetics, and longevity"}, {"id": "0ef879cc-25e9-42f6-9a44-6e9b95094d79", "type": "concept", "title": "Body as microcosm"}, {"id": "6e84f8ac-8e84-4387-bd65-8781fb899757", "type": "concept", "title": "Nature, non-coercion, and ecological readings"}], "description": "Students explore practices of body, cosmos, and environment."}]}, {"id": "af3ffd7c-7198-4238-a98b-7e735a69468a", "type": "topic", "title": "Confucianism and East Asian Social Ethics: Ren, Li, Filiality, Education, Statecraft, and Modernity", "description": "This module treats Confucian traditions as ethical, ritual, political, familial, educational, and religious-cultural formations.", "children": [{"id": "930d494f-a9b1-441d-ad49-2f195da988b3", "type": "subtopic", "title": "Classical Confucian thought", "children": [{"id": "0dabfce3-602b-402f-9547-40ef13f493ee", "type": "concept", "title": "Confucius, Mencius, Xunzi, Analects, ren, li, yi, xiao, junzi, and ritual cultivation"}, {"id": "17cad30b-4488-4a7c-aaa1-5b0c786c27ea", "type": "concept", "title": "Family, education, music, governance, and moral exemplarity"}, {"id": "16ac066c-4323-4ddb-81ee-c84532917dc6", "type": "concept", "title": "Human nature and moral development"}], "description": "Students learn foundational ethical and social concepts."}, {"id": "21c2b41c-5a7e-4142-a863-2d780130ca8a", "type": "subtopic", "title": "Neo-Confucianism and East Asia", "children": [{"id": "f6f409ba-bbb6-4b0e-8019-324c6651c836", "type": "concept", "title": "Zhu Xi, Wang Yangming, principle, material force, self-cultivation, academies, and examination systems"}, {"id": "7c3d8459-4d16-4f14-82e7-44b253468703", "type": "concept", "title": "Korea, Japan, Vietnam, and statecraft"}, {"id": "1995a362-2331-4e73-8f00-1a424ba222ac", "type": "concept", "title": "Confucianism and Buddhism/Daoism"}], "descriptio